332|static int
333|yaml_parser_parse_stream_start(yaml_parser_t *parser, yaml_event_t *event)
334|{
335|    yaml_token_t *token;
336|
337|    token = PEEK_TOKEN(parser);
338|    if (!token) return 0;
339|
340|    if (token->type != YAML_STREAM_START_TOKEN) {
341|        return yaml_parser_set_parser_error(parser,
342|                "did not find expected <stream-start>", token->start_mark);
343|    }
344|
345|    parser->state = YAML_PARSE_IMPLICIT_DOCUMENT_START_STATE;
346|    STREAM_START_EVENT_INIT(*event, token->data.stream_start.encoding,
347|            token->start_mark, token->start_mark);
348|    SKIP_TOKEN(parser);
349|
350|    return 1;
351|}

984|static int
985|yaml_parser_parse_flow_sequence_entry(yaml_parser_t *parser,
986|        yaml_event_t *event, int first)
987|{
988|    yaml_token_t *token;
989|
990|    if (first) {
991|        token = PEEK_TOKEN(parser);
992|        if (!PUSH(parser, parser->marks, token->start_mark))
993|            return 0;
994|        SKIP_TOKEN(parser);
995|    }
996|
997|    token = PEEK_TOKEN(parser);
998|    if (!token) return 0;
999|
1000|    if (token->type != YAML_FLOW_SEQUENCE_END_TOKEN)
1001|    {
1002|        if (!first) {
1003|            if (token->type == YAML_FLOW_ENTRY_TOKEN) {
1004|                SKIP_TOKEN(parser);
1005|                token = PEEK_TOKEN(parser);
1006|                if (!token) return 0;
1007|            }
1008|            else {
1009|                return yaml_parser_set_parser_error_context(parser,
1010|                        "while parsing a flow sequence", POP(parser, parser->marks),
1011|                        "did not find expected ',' or ']'", token->start_mark);
1012|            }
1013|        }
1014|
1015|        if (token->type == YAML_KEY_TOKEN) {
1016|            parser->state = YAML_PARSE_FLOW_SEQUENCE_ENTRY_MAPPING_KEY_STATE;
1017|            MAPPING_START_EVENT_INIT(*event, NULL, NULL,
1018|                    1, YAML_FLOW_MAPPING_STYLE,
1019|                    token->start_mark, token->end_mark);
1020|            SKIP_TOKEN(parser);
1021|            return 1;
1022|        }
1023|
1024|        else if (token->type != YAML_FLOW_SEQUENCE_END_TOKEN) {
1025|            if (!PUSH(parser, parser->states,
1026|                        YAML_PARSE_FLOW_SEQUENCE_ENTRY_STATE))
1027|                return 0;
1028|            return yaml_parser_parse_node(parser, event, 0, 0);
1029|        }
1030|    }
1031|
1032|    parser->state = POP(parser, parser->states);
1033|    (void)POP(parser, parser->marks);
1034|    SEQUENCE_END_EVENT_INIT(*event, token->start_mark, token->end_mark);
1035|    SKIP_TOKEN(parser);
1036|    return 1;
1037|}

