181|YAML_DECLARE(int)
182|yaml_parser_parse(yaml_parser_t *parser, yaml_event_t *event)
183|{
184|    assert(parser);     /* Non-NULL parser object is expected. */
185|    assert(event);      /* Non-NULL event object is expected. */
186|
187|    /* Erase the event object. */
188|
189|    memset(event, 0, sizeof(yaml_event_t));
190|
191|    /* No events after the end of the stream or error. */
192|
193|    if (parser->stream_end_produced || parser->error ||
194|            parser->state == YAML_PARSE_END_STATE) {
195|        return 1;
196|    }
197|
198|    /* Generate the next event. */
199|
200|    return yaml_parser_state_machine(parser, event);
