326|/*
327| * Parse the production:
328| * stream   ::= STREAM-START implicit_document? explicit_document* STREAM-END
329| *              ************
330| */
331|
332|static int
333|yaml_parser_parse_stream_start(yaml_parser_t *parser, yaml_event_t *event)
334|{
335|    yaml_token_t *token;
336|
337|    token = PEEK_TOKEN(parser);
338|    if (!token) return 0;
339|
340|    if (token->type != YAML_STREAM_START_TOKEN) {
341|        return yaml_parser_set_parser_error(parser,
342|                "did not find expected <stream-start>", token->start_mark);
343|    }
344|
345|    parser->state = YAML_PARSE_IMPLICIT_DOCUMENT_START_STATE;
346|    STREAM_START_EVENT_INIT(*event, token->data.stream_start.encoding,
347|            token->start_mark, token->start_mark);
348|    SKIP_TOKEN(parser);
349|
350|    return 1;
351|}
352|
353|/*
354| * Parse the productions:
355| * implicit_document    ::= block_node DOCUMENT-END*
356| *                          *
357| * explicit_document    ::= DIRECTIVE* DOCUMENT-START block_node? DOCUMENT-END*
358| *                          *************************
359| */
360|
361|static int
362|yaml_parser_parse_document_start(yaml_parser_t *parser, yaml_event_t *event,
363|        int implicit)
364|{
365|    yaml_token_t *token;
366|    yaml_version_directive_t *version_directive = NULL;
367|    struct {
368|        yaml_tag_directive_t *start;
369|        yaml_tag_directive_t *end;
370|    } tag_directives = { NULL, NULL };
371|
372|    token = PEEK_TOKEN(parser);
373|    if (!token) return 0;
374|
375|    /* Parse extra document end indicators. */
376|
377|    if (!implicit)
378|    {
379|        while (token->type == YAML_DOCUMENT_END_TOKEN) {
380|            SKIP_TOKEN(parser);
381|            token = PEEK_TOKEN(parser);
382|            if (!token) return 0;
383|        }
384|    }
385|
386|    /* Parse an implicit document. */
387|
388|    if (implicit && token->type != YAML_VERSION_DIRECTIVE_TOKEN &&
389|            token->type != YAML_TAG_DIRECTIVE_TOKEN &&
390|            token->type != YAML_DOCUMENT_START_TOKEN &&
391|            token->type != YAML_STREAM_END_TOKEN)
392|    {
393|        if (!yaml_parser_process_directives(parser, NULL, NULL, NULL))
394|            return 0;
395|        if (!PUSH(parser, parser->states, YAML_PARSE_DOCUMENT_END_STATE))
396|            return 0;
397|        parser->state = YAML_PARSE_BLOCK_NODE_STATE;
398|        DOCUMENT_START_EVENT_INIT(*event, NULL, NULL, NULL, 1,
399|                token->start_mark, token->start_mark);
400|        return 1;
401|    }
402|
403|    /* Parse an explicit document. */
404|
405|    else if (token->type != YAML_STREAM_END_TOKEN)
406|    {
407|        yaml_mark_t start_mark, end_mark;
408|        start_mark = token->start_mark;
409|        if (!yaml_parser_process_directives(parser, &version_directive,
410|                    &tag_directives.start, &tag_directives.end))
411|            return 0;
412|        token = PEEK_TOKEN(parser);
413|        if (!token) goto error;
414|        if (token->type != YAML_DOCUMENT_START_TOKEN) {
415|            yaml_parser_set_parser_error(parser,
416|                    "did not find expected <document start>", token->start_mark);
417|            goto error;
418|        }
419|        if (!PUSH(parser, parser->states, YAML_PARSE_DOCUMENT_END_STATE))
420|            goto error;
421|        parser->state = YAML_PARSE_DOCUMENT_CONTENT_STATE;
422|        end_mark = token->end_mark;
423|        DOCUMENT_START_EVENT_INIT(*event, version_directive,
424|                tag_directives.start, tag_directives.end, 0,
425|                start_mark, end_mark);
426|        SKIP_TOKEN(parser);
427|        version_directive = NULL;
428|        tag_directives.start = tag_directives.end = NULL;
429|        return 1;
430|    }
431|
432|    /* Parse the stream end. */
433|
434|    else
435|    {
436|        parser->state = YAML_PARSE_END_STATE;
437|        STREAM_END_EVENT_INIT(*event, token->start_mark, token->end_mark);
438|        SKIP_TOKEN(parser);
439|        return 1;
440|    }
441|
442|error:
443|    yaml_free(version_directive);
444|    while (tag_directives.start != tag_directives.end) {
445|        yaml_free(tag_directives.end[-1].handle);
446|        yaml_free(tag_directives.end[-1].prefix);
447|        tag_directives.end --;
448|    }
449|    yaml_free(tag_directives.start);
450|    return 0;
451|}
