1267|/*
1268| * Parse directives.
1269| */
1270|
1271|static int
1272|yaml_parser_process_directives(yaml_parser_t *parser,
1273|        yaml_version_directive_t **version_directive_ref,
1274|        yaml_tag_directive_t **tag_directives_start_ref,
1275|        yaml_tag_directive_t **tag_directives_end_ref)
1276|{
1277|    yaml_tag_directive_t default_tag_directives[] = {
1278|        {(yaml_char_t *)"!", (yaml_char_t *)"!"},
1279|        {(yaml_char_t *)"!!", (yaml_char_t *)"tag:yaml.org,2002:"},
1280|        {NULL, NULL}
1281|    };
1282|    yaml_tag_directive_t *default_tag_directive;
1283|    yaml_version_directive_t *version_directive = NULL;
1284|    struct {
1285|        yaml_tag_directive_t *start;
1286|        yaml_tag_directive_t *end;
1287|        yaml_tag_directive_t *top;
1288|    } tag_directives = { NULL, NULL, NULL };
1289|    yaml_token_t *token;
1290|
1291|    if (!STACK_INIT(parser, tag_directives, yaml_tag_directive_t*))
1292|        goto error;
1293|
1294|    token = PEEK_TOKEN(parser);
1295|    if (!token) goto error;
1296|
1297|    while (token->type == YAML_VERSION_DIRECTIVE_TOKEN ||
1298|            token->type == YAML_TAG_DIRECTIVE_TOKEN)
1299|    {
1300|        if (token->type == YAML_VERSION_DIRECTIVE_TOKEN) {
1301|            if (version_directive) {
1302|                yaml_parser_set_parser_error(parser,
1303|                        "found duplicate %YAML directive", token->start_mark);
1304|                goto error;
1305|            }
1306|            if (token->data.version_directive.major != 1
1307|                    || (
1308|                        token->data.version_directive.minor != 1
1309|                        && token->data.version_directive.minor != 2
1310|                    )) {
1311|                yaml_parser_set_parser_error(parser,
1312|                        "found incompatible YAML document", token->start_mark);
1313|                goto error;
1314|            }
1315|            version_directive = YAML_MALLOC_STATIC(yaml_version_directive_t);
1316|            if (!version_directive) {
1317|                parser->error = YAML_MEMORY_ERROR;
1318|                goto error;
1319|            }
1320|            version_directive->major = token->data.version_directive.major;
1321|            version_directive->minor = token->data.version_directive.minor;
1322|        }
1323|
1324|        else if (token->type == YAML_TAG_DIRECTIVE_TOKEN) {
1325|            yaml_tag_directive_t value;
1326|            value.handle = token->data.tag_directive.handle;
1327|            value.prefix = token->data.tag_directive.prefix;
1328|
1329|            if (!yaml_parser_append_tag_directive(parser, value, 0,
1330|                        token->start_mark))
1331|                goto error;
1332|            if (!PUSH(parser, tag_directives, value))
1333|                goto error;
1334|        }
1335|
1336|        SKIP_TOKEN(parser);
1337|        token = PEEK_TOKEN(parser);
1338|        if (!token) goto error;
1339|    }
1340|
1341|    for (default_tag_directive = default_tag_directives;
1342|            default_tag_directive->handle; default_tag_directive++) {
1343|        if (!yaml_parser_append_tag_directive(parser, *default_tag_directive, 1,
1344|                    token->start_mark))
1345|            goto error;
1346|    }
1347|
1348|    if (version_directive_ref) {
1349|        *version_directive_ref = version_directive;
1350|    }
1351|    if (tag_directives_start_ref) {
1352|        if (STACK_EMPTY(parser, tag_directives)) {
1353|            *tag_directives_start_ref = *tag_directives_end_ref = NULL;
1354|            STACK_DEL(parser, tag_directives);
1355|        }
1356|        else {
1357|            *tag_directives_start_ref = tag_directives.start;
1358|            *tag_directives_end_ref = tag_directives.top;
1359|        }
1360|    }
1361|    else {
1362|        STACK_DEL(parser, tag_directives);
1363|    }
1364|
1365|    if (!version_directive_ref)
1366|        yaml_free(version_directive);
1367|    return 1;
1368|
1369|error:
1370|    yaml_free(version_directive);
1371|    while (!STACK_EMPTY(parser, tag_directives)) {
1372|        yaml_tag_directive_t tag_directive = POP(parser, tag_directives);
1373|        yaml_free(tag_directive.handle);
1374|        yaml_free(tag_directive.prefix);
1375|    }
1376|    STACK_DEL(parser, tag_directives);
1377|    return 0;
1378|}
1379|
1380|/*
1381| * Append a tag directive to the directives stack.
1382| */
1383|
1384|static int
1385|yaml_parser_append_tag_directive(yaml_parser_t *parser,
1386|        yaml_tag_directive_t value, int allow_duplicates, yaml_mark_t mark)
1387|{
1388|    yaml_tag_directive_t *tag_directive;
1389|    yaml_tag_directive_t copy = { NULL, NULL };
1390|
1391|    for (tag_directive = parser->tag_directives.start;
1392|            tag_directive != parser->tag_directives.top; tag_directive ++) {
1393|        if (strcmp((char *)value.handle, (char *)tag_directive->handle) == 0) {
1394|            if (allow_duplicates)
1395|                return 1;
1396|            return yaml_parser_set_parser_error(parser,
1397|                    "found duplicate %TAG directive", mark);
1398|        }
1399|    }
1400|
1401|    copy.handle = yaml_strdup(value.handle);
1402|    copy.prefix = yaml_strdup(value.prefix);
1403|    if (!copy.handle || !copy.prefix) {
1404|        parser->error = YAML_MEMORY_ERROR;
1405|        goto error;
1406|    }
1407|
1408|    if (!PUSH(parser, parser->tag_directives, copy))
1409|        goto error;
1410|
1411|    return 1;
1412|
1413|error:
1414|    yaml_free(copy.handle);
1415|    yaml_free(copy.prefix);
1416|    return 0;
1417|}
