37|        }
38|
39|        else if (strcmp(argv[k], "-c") == 0
40|                || strcmp(argv[k], "--canonical") == 0) {
41|            canonical = 1;
42|        }
43|
44|        else if (strcmp(argv[k], "-u") == 0
45|                || strcmp(argv[k], "--unicode") == 0) {
46|            unicode = 1;
47|        }
